#include <memory>
#include <iostream>

struct ClassA {};

int main() {
    std::auto_ptr<ClassA> ptr1(new ClassA);

    // Check initial state
    std::cout << "ptr1 before copy: " << (ptr1.get() != nullptr) << "\n";

    // Ownership Transfer via Copy Constructor
    std::auto_ptr<ClassA> ptr2(ptr1);

    // Check state after transfer
    // ptr1 is now null; ptr2 owns the resource.
    std::cout << "ptr1 after copy: " << (ptr1.get() != nullptr) << "\n";

    // Assignment also transfers ownership
    std::auto_ptr<ClassA> ptr3;
    ptr3 = ptr2; // ptr2 becomes null
}
